return array(array('bangla','কোন প্রকার শব্দের মূল নির্ধারণ করা যায় না?',array('তদ্ভব','দেশি','অর্ধ-তৎসম','তৎসম'),1,'দেশি শব্দ বাংলা ভূখণ্ডের আদিম অধিবাসীদের (কোল, মুণ্ডা প্রভৃতি) ভাষা থেকে এসেছে, তাই এর মূল নির্ণয় করা যায় না। কুড়ি, পেট, চুলা এর উদাহরণ।',false,'ok',1),array('bangla','কোনটি অর্ধ-তৎসম শব্দ?',array('সূর্য','সুনাম','জ্যোছনা','জবান'),2,'‘জ্যোছনা’ শব্দটি তৎসম ‘জ্যোৎস্না’ থেকে কিছুটা বদলে এসেছে, তাই এটি অর্ধ-তৎসম। ‘সূর্য’ তৎসম এবং ‘জবান’ ফারসি শব্দ।',false,'ok',2),array('bangla','‘ধাতুরূপ’ ব্যাকরণের কোন অংশে আলোচিত হয়?',array('রূপতত্ত্ব','ধ্বনিতত্ত্ব','বাক্যতত্ত্ব','ছন্দতত্ত্ব'),0,'ধাতুরূপ, শব্দরূপ, প্রত্যয়, সমাস ইত্যাদি শব্দ গঠনের বিষয়, যা রূপতত্ত্ব (শব্দতত্ত্ব) অংশে আলোচিত হয়।',false,'ok',3),array('bangla','যে শব্দকে বা কোন শব্দের যে অংশকে আর কোন ক্ষুদ্রতর অংশে ভাগ করা যায় না, তাকে কী বলে?',array('সন্ধি','প্রকৃতি','প্রত্যয়','সমাস'),1,'শব্দ বা শব্দের যে মূল অংশকে আর ভাঙা যায় না, তাকে প্রকৃতি বলে। প্রকৃতির পরে যে বর্ণ বা বর্ণসমষ্টি যুক্ত হয়, তা প্রত্যয়।',false,'ok',4),array('bangla','‘আহ্বান’ এর প্রকৃত উচ্চারণ কোনটি?',array('আওভান','আহবান','আহ্বান','আবহান'),0,'হ-এর সঙ্গে ব-ফলা যুক্ত হলে উচ্চারণে ‘ওভ’ ধ্বনি শোনা যায়। তাই ‘আহ্বান’-এর উচ্চারণ ‘আওভান’।',false,'ok',5),array('bangla','কবাট > কপাট, ধোবা > ধোপা কিসের উদাহরণ?',array('ধ্বনি বিপর্যয়','অভিশ্রুতি','ব্যঞ্জন চ্যুতি','ব্যঞ্জন বিকৃতি'),3,'শব্দের মাঝে কোনো ব্যঞ্জন বদলে নতুন ব্যঞ্জন এলে তাকে ব্যঞ্জন বিকৃতি বলে। এখানে ‘ব’ বদলে ‘প’ হয়েছে।',false,'ok',6),array('bangla','কোনটি স্বরভক্তির উদাহরণ?',array('বিলিতি','পিরীতি','বসতি','জানালা'),1,'যুক্তব্যঞ্জনের মাঝে স্বরধ্বনি ঢুকিয়ে উচ্চারণ সহজ করাকে স্বরভক্তি বা বিপ্রকর্ষ বলে। প্রীতি > পিরীতি এর উদাহরণ, কারণ এখানে ‘প্র’ ভেঙে ‘পির’ হয়েছে।',false,'ok',7),array('bangla','কোন বানানটি ‘ষ-ত্ব’ বিধানের নিয়মে শুদ্ধ?',array('মাষ্টার','পোষাক','সংস্কার','পোষ্ট'),2,'বিদেশি শব্দে ষ হয় না, তাই শুদ্ধ রূপ মাস্টার, পোশাক ও পোস্ট। ‘সংস্কার’ বানানটি শুদ্ধ, কারণ সম্ + কৃ যোগে স্ বসে, সেখানে মূর্ধন্য ষ হয় না।',false,'ok',8),array('bangla','নিচের কোনটি নিপাতনে সিদ্ধ সন্ধি?',array('পরিষ্কার','ষড়ানন','সংস্কার','আশ্চর্য'),3,'আ + চর্য = আশ্চর্য; এখানে ‘শ’ আসার কোনো নিয়ম নেই, তাই এটি নিপাতনে সিদ্ধ সন্ধি। ষড়ানন (ষট্ + আনন) সাধারণ ব্যঞ্জন সন্ধি।',false,'ok',9),array('bangla','‘পশ্বধম’ শব্দটির সঠিক সন্ধি বিচ্ছেদ কী?',array('পশু + অধম','পশ্বা + অধম','পশ্বা + ধম','পশু + ধম'),0,'উ-কারের পরে উ ছাড়া অন্য স্বর এলে উ বদলে ‘ব’-ফলা হয়। তাই পশু + অধম = পশ্বধম।',false,'ok',10),array('bangla','কোনটি আ-প্রত্যয় যোগে সাধিত স্ত্রী-বাচক শব্দ?',array('গায়িকা','নায়িকা','প্রথমা','বালিকা'),2,'প্রথম + আ = প্রথমা, এখানে সরাসরি আ-প্রত্যয় যোগ হয়েছে। তবে ব্যাকরণে ‘অক’-অন্ত শব্দে আ-প্রত্যয়ের ফলে ‘ইকা’ হয় (গায়িকা, নায়িকা, বালিকা) বলেও ধরা হয়, তাই প্রশ্নটি দ্ব্যর্থক।',false,'unsure',11),array('bangla','ধ্বনাত্মক দ্বিরুক্তির উদাহরণ কোনটি?',array('চোখে চোখে','ঘেউ ঘেউ','কেউ কেউ','চুপচাপ'),1,'প্রকৃতির শব্দ বা ধ্বনি অনুকরণ করে গঠিত দ্বিরুক্তিকে ধ্বন্যাত্মক দ্বিরুক্তি বলে। কুকুরের ডাক ‘ঘেউ ঘেউ’ এর উদাহরণ।',false,'ok',12),array('bangla','কোন সমাসে সমস্যমান পদের বিভক্তি লোপ পায় না?',array('নিত্য','প্রাদি','উপপদ','অলুক'),3,'যে সমাসে সমস্যমান পদের বিভক্তি লোপ পায় না, তাকে অলুক সমাস বলে। যেমন: গায়ে-হলুদ, ঘোড়ার ডিম।',false,'ok',13),array('bangla','‘ডাক্তার ডাক’ বাক্যটিতে ‘ডাক্তার’ কোন কারকে কোন বিভক্তি?',array('কর্মে ষষ্ঠী','কর্মে শূন্য','কর্তায় শূন্য','সম্বন্ধে ষষ্ঠী'),1,'কাজটি (ডাকা) ডাক্তারকে লক্ষ্য করে, তাই ‘ডাক্তার’ কর্ম কারক। এতে কোনো বিভক্তি চিহ্ন যুক্ত হয়নি, অর্থাৎ শূন্য বিভক্তি।',false,'ok',14),array('bangla','আঘাত পায়নি এমন বোঝাতে কোনটি হবে?',array('অনাহত','অনাঘাত','সর্বংসহা','অবিনশ্বর'),0,'যে আঘাত পায়নি, এক কথায় তাকে ‘অনাহত’ বলে (ন আহত)। সব কিছু সহ্য করে যে, তাকে বলে সর্বংসহা।',false,'ok',15),array('bangla','প্রত্যেক ভাষার কয়টি মৌলিক অংশ আছে?',array('দুইটি','তিনটি','চারটি','পাঁচটি'),2,'বাংলা ব্যাকরণের প্রচলিত পাঠ্যবই অনুযায়ী প্রত্যেক ভাষার চারটি মৌলিক অংশ: ধ্বনি, শব্দ, বাক্য ও অর্থ।',false,'ok',16),array('english','[Q. 17 - 20 Select the word that is most closely OPPOSITE in meaning to the original word.] QUIESCENT',array('Dormant','Weak','Unconcerned','Active'),3,'‘Quiescent’ অর্থ নিষ্ক্রিয় বা স্থির; এর বিপরীত ‘active’ (সক্রিয়)। ‘Dormant’ এর সমার্থক।',false,'ok',17),array('english','LOQUACIOUS',array('Talkative','Reticent','Garrulous','Verbose'),1,'‘Loquacious’ অর্থ বাচাল। Talkative, garrulous ও verbose এর সমার্থক, আর বিপরীত ‘reticent’ (স্বল্পভাষী)।',false,'ok',18),array('english','NIGGARDLY',array('Generous','Stingy','Thrifty','Frugal'),0,'‘Niggardly’ অর্থ কৃপণ; এর বিপরীত ‘generous’ (উদার)। Stingy, thrifty ও frugal কাছাকাছি অর্থের শব্দ।',false,'ok',19),array('english','HAPHAZARD',array('Indifferent','Fortuitous','Deliberate','Accidental'),2,'‘Haphazard’ অর্থ এলোমেলো বা পরিকল্পনাহীন; এর বিপরীত ‘deliberate’ (পরিকল্পিত, ইচ্ছাকৃত)।',false,'ok',20),array('english','[Q. 21-24: In this sections you must choose the word which best fits each space in the text below. The principal advantage in having a clear cut objective of business is that it does not derail; the enterprise does not stray ____(21)_____ the direct route that it has set for ____( 22 )____ . Enterprises with well-defined objectives can conveniently undertake _____(23)_____ and follow long range development polices. Recognition of objectives _____(24)_____ the temptation to compromise long range objects for short term gains and improves coordination in work and consistency in policy.] Choose the appropriate word.',array('on','from','along','towards'),1,'‘Stray from’ অর্থ কোনো পথ থেকে বিচ্যুত হওয়া। প্রতিষ্ঠান তার নির্ধারিত সরল পথ থেকে সরে যায় না, তাই ‘from’ বসবে।',false,'ok',21),array('english','Choose the appropriate word.',array('others','industry','itself','government'),2,'প্রতিষ্ঠান নিজের জন্য পথ ঠিক করেছে, তাই reflexive pronoun ‘itself’ বসবে (the route that it has set for itself)।',false,'ok',22),array('english','Choose the appropriate word.',array('production','research','audit','apraisal'),1,'দীর্ঘমেয়াদি উন্নয়ন নীতির সঙ্গে ‘research’ (গবেষণা) শব্দটিই মেলে: স্পষ্ট লক্ষ্য থাকলে প্রতিষ্ঠান সহজে গবেষণা করতে পারে।',false,'ok',23),array('english','Choose the appropriate word.',array('invites','removes','defers','shifts'),1,'লক্ষ্য স্পষ্টভাবে জানা থাকলে স্বল্পমেয়াদি লাভের জন্য আপস করার প্রলোভন দূর হয়। তাই ‘removes’ বসবে।',false,'ok',24),array('english','[Q25-28: Read the following passage and answer the questions given below: Our voyage was very prosperous, but I shall not trouble the reader with a journal of it. The captain called in at one or two ports and sent in his long boat for provisions and freshwater, but I never went out of the ship still we came into the Downs, which was on the 3rd day of June, 1706, about nine months after my escape. I offered to leave my goods in security for payment of my freight, but the captain protested he would not receive one fanning. We took kind leave of each other, and I made him promise that he would come to see me at my house in Redriff. I hired house and a guide for five shillings which I borrowed from the captain] When the writer uses the word \'prosperous\' to describe means that',array('it made him rich','it made him healthy','it was uneventful','it was very pleasant'),2,'লেখক বলেছেন যাত্রার বিস্তারিত বিবরণ দিয়ে পাঠককে বিরক্ত করবেন না, অর্থাৎ যাত্রায় উল্লেখযোগ্য কিছু ঘটেনি। তাই ‘prosperous’ এখানে নির্বিঘ্ন বা uneventful অর্থে, যদিও কেউ ‘pleasant’-ও ধরতে পারেন।',false,'unsure',25),array('english','In the context of the passage, the word \'provisions\' means',array('mainly security','money','mainly food','mainly ammunition'),2,'জাহাজ বন্দরে নৌকা পাঠিয়ে provisions ও পানি সংগ্রহ করেছিল। এখানে provisions মানে মূলত খাদ্যসামগ্রী।',false,'ok',26),array('english','For the payment of the author\'s freight the captain',array('refused to accept any money','kept his goods as security','protested against being paid','accepted a sum of money'),0,'লেখক ভাড়ার নিশ্চয়তা হিসেবে মাল রাখতে চাইলেও ক্যাপ্টেন জানান তিনি এক ফার্দিংও নেবেন না, অর্থাৎ কোনো টাকা নিতে অস্বীকার করেন।',false,'ok',27),array('english','From the passage, it is clear that the captain\'s attitude to the author was',array('one of hostility','one of extreme friendliness and kindness','one of indifference','one of disgust and irritation'),1,'ক্যাপ্টেন ভাড়া নেননি, লেখককে টাকা ধার দিয়েছেন এবং বিদায়ও হয়েছে আন্তরিকভাবে। এতে তাঁর অত্যন্ত বন্ধুত্বপূর্ণ ও সদয় মনোভাব বোঝা যায়।',false,'ok',28),array('english','[Q. 29 - 33: Each sentence has four parts, marked (A), (B), (C) and (D). Identify the incorrect or inappropriate part of the sentence.] Guppies are sometimes call (A) rainbow fish due to (B) the bright (C) colors of the males (D).',array('call','due to','bright','the males'),0,'বাক্যটি passive voice, তাই ‘are sometimes called’ হবে। ‘call’ ভুল।',false,'ok',29),array('english','The peculiar (A) dress he wears (B) gave him a comical (C) appearances (D).',array('peculiar','wears','comical','appearances'),3,'‘a’ article-এর পরে singular noun বসে, তাই ‘a comical appearance’ হবে; ‘appearances’ ভুল। তবে wears/gave-এর কালের অমিলকেও (wore হওয়া উচিত) ভুল ধরা যায়।',false,'unsure',30),array('english','The exhistence (A) and attributes (B) of the colonial (C) army were decisive (D) to the outbreak of Civil War.',array('exhistence','attributes','colonial','decisive'),0,'‘exhistence’ বানান ভুল, সঠিক বানান ‘existence’।',false,'ok',31),array('english','He who is indeed of the brotherhood (A) does not voyage (B) in quest of the picturisque (C) but of certain jolly humors (D).',array('brotherhood','voyage','picturisque','humors'),2,'‘picturisque’ বানান ভুল, সঠিক বানান ‘picturesque’ (মনোরম দৃশ্য)।',false,'ok',32),array('english','Roshni was found (A) of pets and she was a proud (B) owner of many unique (C) animals (D).',array('found','proud','unique','animals'),0,'‘Fond of’ অর্থ কোনো কিছু পছন্দ করা; এখানে ‘found’ ভুল, হবে ‘Roshni was fond of pets’।',false,'ok',33),array('math','The ratio of quantity of water in fresh fruits to that of dry fruits is 7 : 2. If 400 Kg of dry fruits contain 50 Kg of water then find the weight of the water in same fruits when they were fresh?',array('100 Kg','150 Kg','175 Kg','125 Kg'),2,'তাজা ও শুকনো ফলে পানির অনুপাত 7 : 2। শুকনো অবস্থায় পানি 50 কেজি হলে 2 অংশ = 50, তাই তাজা অবস্থায় পানি = 7 × 25 = 175 কেজি।',false,'ok',34),array('math','What would be the measure of the diagonal of a square whose area is equal to 578 cm²?',array('34 cm','38 cm','32 cm','42 cm'),0,'বর্গের কর্ণ² = 2 × ক্ষেত্রফল = 2 × 578 = 1156, তাই কর্ণ = √1156 = 34 সেমি।',false,'ok',35),array('math','The cost price of a table and a chair together is Tk. 690. If the table costs 30% more than the chair, then find the cost price of the table and the chair respectively?',array('Tk. 300 and Tk. 390','Tk. 390 and Tk. 300','Tk. 480 and Tk. 210','Tk. 400 and Tk. 290'),1,'চেয়ারের দাম x হলে টেবিলের দাম 1.3x। তাহলে 2.3x = 690, ফলে x = 300। টেবিল 390 টাকা ও চেয়ার 300 টাকা।',false,'ok',36),array('math','6(3/4) x 13(1/3) + 22 x ? = 30% of 520',array('13','13.5','12','None of these'),3,'6¾ × 13⅓ = (27/4) × (40/3) = 90 এবং 520-এর 30% = 156। তাহলে 22 × ? = 156 − 90 = 66, অর্থাৎ ? = 3, যা বিকল্পে নেই।',false,'ok',37),array('math','In the question two equations numbers I and II are given. You have to solve both the equations and give answer. I. 6x² - 11x + 4 = 0 II. 50y² - 25y + 3 = 0',array('x < y','x ≤ y','x > y','x ≥ y'),2,'6x² − 11x + 4 = 0 সমাধান করলে x = 4/3 বা 1/2। 50y² − 25y + 3 = 0 থেকে y = 0.3 বা 0.2। x-এর দুটি মানই y-এর দুটি মানের চেয়ে বড়, তাই x > y।',false,'ok',38),array('math','There are 3 green, 4 orange and 5 white color bulbs in a bag. If a bulb is picked at random, what is the probability of having either a green or a white bulb?',array('2/3','3/4','4/3','2/5'),0,'মোট বাল্ব 12টি, তার মধ্যে সবুজ বা সাদা 3 + 5 = 8টি। তাই সম্ভাবনা 8/12 = 2/3।',false,'ok',39),array('math','The ratio of Pens and Pencils in a shop is 3 : 2 respectively. The average number of Pens and Pencils is 180. What is the number of Pencils in the shop?',array('444','244','344','144'),3,'কলম ও পেন্সিলের গড় 180, তাই মোট 360। পেন্সিল = 360 × 2/5 = 144।',false,'ok',40),array('math','P, Q and R start a business. P invests 3 times as much as Q invests and Q invests 2/3 rd as much as R invests. Find the ratio of capitals of P, Q and R?',array('3 : 2 : 6','6 : 2 : 3','2 : 6 : 3','5 : 2 : 3'),1,'R = 3 ধরলে Q = (2/3) × 3 = 2 এবং P = 3 × 2 = 6। তাই P : Q : R = 6 : 2 : 3।',false,'ok',41),array('math','A dishonest milkman professes to sell his milk at cost price but he mixes it with water and thereby gains 25%. The percentage of water in the mixture is',array('8%','10%','20%','15%'),2,'ক্রয়মূল্যে বিক্রি করে 25% লাভ মানে প্রতি 100 একক দুধে 25 একক পানি মেশানো। মিশ্রণ 125 এককে পানির হার = 25/125 = 20%।',false,'ok',42),array('math','How many iron rods, each of length 7m and diameter 2cm can be made out of 0.88m³ of iron?',array('400','200','300','100'),0,'একটি রডের আয়তন = πr²h = (22/7) × (0.01)² × 7 = 0.0022 ঘনমিটার। রডের সংখ্যা = 0.88 ÷ 0.0022 = 400।',false,'ok',43),array('math','A is three times as old as B, C was twice as old as A four years ago. In four years time, A will be 31. What are the present ages of B and C?',array('45, 10','9, 50','10, 50','50, 15'),1,'৪ বছর পর A-এর বয়স হবে 31, তাই এখন A = 27 এবং B = 27/3 = 9। চার বছর আগে C ছিল A-এর দ্বিগুণ: C − 4 = 2 × 23 = 46, তাই C = 50।',false,'ok',44),array('math','If 3√5 + √125 = 17.88, then what will be the value of √80 + 6√5 = ?',array('13.41','20.46','21.66','22.35'),3,'3√5 + √125 = 3√5 + 5√5 = 8√5 = 17.88, তাই √5 = 2.235। এখন √80 + 6√5 = 4√5 + 6√5 = 10√5 = 22.35।',false,'ok',45),array('math','What will be simple interest for 1 year and 4 months on a sum of Tk. 25,800 at the rate of 14% per annum?',array('Tk. 4816','Tk. 2580','Tk. 4815','None of these'),0,'সময় 1 বছর 4 মাস = 4/3 বছর। সরল সুদ = 25800 × 14% × 4/3 = 3612 × 4/3 = 4816 টাকা।',false,'ok',46),array('math','An error 2% in excess is made while measuring the side of a square. The percentage of error in the calculated area of the square is',array('2.00%','4.04%','2.02%','4.00%'),1,'বাহু 2% বেশি মাপা হলে ক্ষেত্রফল হয় (1.02)² = 1.0404 গুণ। তাই ক্ষেত্রফলে ভুল 4.04%।',false,'ok',47),array('math','A man took loan from a bank at the rate of 12% p.a. simple interest. After 3 years he had to pay Tk. 5,400 interest only for the period. The principal account borrowed by him was',array('Tk. 20,000','Tk. 10,000','Tk. 2,000','Tk. 15,000'),3,'আসল = সুদ ÷ (হার × সময়) = 5400 ÷ (0.12 × 3) = 5400 ÷ 0.36 = 15,000 টাকা।',false,'ok',48),array('math','A boat covers a certain distance downstream in 1 hour, while it comes back in 1.5 hour. If the speed of the stream be 3 km/hr, what is the speed of the boat in still water?',array('12 km/hr','15 km/hr','13 km/hr','14 km/hr'),1,'নৌকার স্থির পানিতে বেগ b হলে দূরত্ব সমান বলে (b+3) × 1 = (b−3) × 1.5। এতে 0.5b = 7.5, অর্থাৎ b = 15 কিমি/ঘণ্টা।',false,'ok',49),array('math','Tk. 385 has been divided among A, B, C in such a way that A receives (2/9)th of what B and C together receive. The A\'s share is?',array('Tk. 77','Tk. 82.50','Tk. 70','Tk. 85'),2,'A = (2/9)(B+C) হলে A : (B+C) = 2 : 9। তাই A-এর অংশ = 385 × 2/11 = 70 টাকা।',false,'ok',50),array('math','Mother\'s age today is thrice as her daughter\'s. After 10 years it would be just double. How old is the daughter today?',array('10 years','9 years','8 years','11 years'),0,'মেয়ের বয়স d হলে মায়ের 3d। ১০ বছর পর 3d + 10 = 2(d + 10), তাই d = 10 বছর।',false,'ok',51),array('math','A boat can travel with a speed of 13 km/hr in still water. If the speed of the stream is 4 km/hr, find the time taken by the boat to go to 68 km downstream?',array('3 hours','5 hours','6 hours','4 hours'),3,'ভাটির দিকে কার্যকর বেগ = 13 + 4 = 17 কিমি/ঘণ্টা। তাই 68 কিমি যেতে সময় = 68/17 = 4 ঘণ্টা।',false,'ok',52),array('math','In what time will the simple interest of Tk. 400 at 10% per annum be the same as the simple interest on Tk. 1000 for 4 year at 4% per annum?',array('3 years','4 years','5 years','6 years'),1,'1000 টাকার 4 বছরে 4% হারে সুদ = 160 টাকা। 400 টাকায় 10% হারে বছরে সুদ 40 টাকা, তাই সময় = 160/40 = 4 বছর।',false,'ok',53),array('math','A student multiplied a number by 3/5 instead of 5/3, What is the percentage error in the calculation?',array('50%','54%','60%','64%'),3,'সঠিক ফল 5/3 কিন্তু পাওয়া গেছে 3/5; পার্থক্য 5/3 − 3/5 = 16/15। শতকরা ভুল = (16/15) ÷ (5/3) × 100 = 16/25 × 100 = 64%।',false,'ok',54),array('math','A car covers four successive 7 km distance at speeds of 10 km/hr, 20 km/hr, 30 km/hr and 60 km/hr respectively. Its average speed over this distance is',array('40 km/hr','30 km/hr','20 km/hr','50 km/hr'),2,'চার ধাপে মোট সময় = 7/10 + 7/20 + 7/30 + 7/60 = 7 × (12/60) = 1.4 ঘণ্টা। মোট দূরত্ব 28 কিমি, তাই গড় বেগ = 28/1.4 = 20 কিমি/ঘণ্টা।',false,'ok',55),array('math','A total age of A and B is 12 years more than the total age of B and C. C is how many years younger than A?',array('12 years','13 years','14 years','15 years'),0,'A + B = B + C + 12 থেকে দুই পাশের B বাদ দিলে A − C = 12। অর্থাৎ C, A-এর চেয়ে 12 বছরের ছোট।',false,'ok',56),array('computer','Which of the following is system software?',array('Operating System','Compiler','Utilities','All of these'),3,'Operating system, compiler ও utility program তিনটিই system software, কারণ এরা হার্ডওয়্যার পরিচালনা করে এবং অন্য প্রোগ্রাম চালানোর পরিবেশ দেয়।',false,'ok',57),array('computer','The operating system creates from the physical computer.',array('Virtual computers','Virtual space','Virtual device','None of these'),0,'Operating system প্রতিটি ব্যবহারকারী বা প্রোগ্রামকে ভৌত কম্পিউটারের একটি ‘virtual computer’ রূপ দেয়, যেন প্রত্যেকে আলাদা যন্ত্র ব্যবহার করছে।',false,'ok',58),array('computer','Which is not application software?',array('Page Maker','Windows NT','WinWord XP','Photoshop'),1,'Windows NT একটি operating system, অর্থাৎ system software। PageMaker, WinWord ও Photoshop হলো application software।',false,'ok',59),array('computer','Which can be used for quick access to commonly used commands and tools?',array('Status bar','Menu bar','Tool bar','Title bar'),2,'Toolbar-এ বহুল ব্যবহৃত কমান্ড ও টুল আইকন আকারে থাকে, ফলে এক ক্লিকে দ্রুত ব্যবহার করা যায়।',false,'ok',60),array('computer','What is the smallest and largest font size available in Font Size tool on formatting toolbar?',array('8 and 68','6 and 72','6 and 68','8 and 72'),3,'MS Word-এর formatting toolbar-এর Font Size তালিকায় সবচেয়ে ছোট মাপ 8 এবং সবচেয়ে বড় মাপ 72। চাইলে হাতে লিখে এর বাইরের মাপও দেওয়া যায়।',false,'ok',61),array('computer','Ctrl + N is used to',array('Save Document','New Document','Open Document','Close Document'),1,'MS Office প্রোগ্রামে Ctrl + N চাপলে নতুন ডকুমেন্ট খোলে। Ctrl + S দিয়ে save এবং Ctrl + O দিয়ে open করা হয়।',false,'ok',62),array('computer','.... formatting is the process of changing the way letters, numbers, punctuation marks, and symbols appear on the screen and in print.',array('Character','Paragraph','Document','Object'),0,'অক্ষর, সংখ্যা ও চিহ্নের ফন্ট, আকার, রং, bold বা italic ইত্যাদি বদলানোকে character formatting বলে।',false,'ok',63),array('computer','You can detect spelling and grammar errors by',array('Press Shift + F7','Press Ctrl+ F7','Press Alt + F7','Press F7'),3,'MS Word-এ F7 চাপলে Spelling and Grammar যাচাই শুরু হয়। Shift + F7 চাপলে খোলে Thesaurus।',false,'ok',64),array('computer','Each excel file is a workbook that contains different sheets. Which of the following cannot be a sheet in workbook?',array('work sheet','data sheet','chart sheet','module sheet'),1,'Excel workbook-এ worksheet, chart sheet ও (পুরনো সংস্করণে) macro/module sheet থাকতে পারে, কিন্তু ‘data sheet’ নামে কোনো sheet নেই।',false,'ok',65),array('computer','What is the short cut key to replace a data with another in excel sheet?',array('Ctrl + R','Ctrl + Shift + R','Ctrl + H','Ctrl + F'),2,'Excel-এ Ctrl + H চাপলে Find and Replace ডায়ালগের Replace ট্যাব খোলে। Ctrl + F শুধু খোঁজার জন্য।',false,'ok',66),array('computer','Which of the following cannot be toggled from View >> Toolbars?',array('Control Toolbox','Revisions','Reviewing','Slides'),3,'পুরনো PowerPoint-এর View > Toolbars মেনুতে Control Toolbox, Revisions ও Reviewing টুলবার আছে। ‘Slides’ কোনো টুলবার নয়, এটি বাম প্যানেলের একটি ট্যাব।',false,'ok',67),array('computer','Which tab is not available on left panel when you open a presentation?',array('Outline','Notes','Slides','All of these'),1,'PowerPoint খুললে বাম প্যানেলে Outline ও Slides ট্যাব থাকে। Notes থাকে স্লাইডের নিচের notes pane-এ, বাম প্যানেলে নয়।',false,'ok',68),array('intl-affairs','Federation Cup, World Cup, Allywyn International Trophy and Challenge Cup are awarded to winners of',array('Tennis','Basketball','Volleyball','Cricket'),2,'ফেডারেশন কাপ, বিশ্বকাপ, অলউইন ইন্টারন্যাশনাল ট্রফি ও চ্যালেঞ্জ কাপ ভলিবলের সঙ্গে যুক্ত পুরস্কার হিসেবে বিভিন্ন সাধারণ জ্ঞানের বইয়ে উল্লেখিত।',false,'unsure',69),array('science','Excessive secretion from the pituitary gland in the children results in',array('increased height','retarded growth','weakening of bones','None of these'),0,'শৈশবে পিটুইটারি গ্রন্থি থেকে growth hormone বেশি নিঃসৃত হলে অতিরিক্ত দৈহিক বৃদ্ধি ঘটে, একে gigantism বলে। কম নিঃসৃত হলে বামনত্ব হয়।',false,'ok',70),array('intl-affairs','When was the International Social Security Association (ISSA) formed?',array('1915','1946','1935','1927'),3,'International Social Security Association (ISSA) ১৯২৭ সালে প্রতিষ্ঠিত হয়। এর সদর দপ্তর জেনেভায়।',false,'ok',71),array('intl-affairs','The headquarter of SpaceX is located in',array('California','London','New York','Moscow'),0,'পরীক্ষার সময়ের তথ্য: SpaceX-এর সদর দপ্তর ছিল ক্যালিফোর্নিয়ার হথর্নে। পরে ২০২৪ সালে প্রতিষ্ঠানটি সদর দপ্তর টেক্সাসের স্টারবেসে সরিয়ে নেওয়ার ঘোষণা দেয়।',false,'timebound',72),array('intl-affairs','Who won the Peace Nobel Prize 2019 for promoting peace and reconciliation?',array('Barack Obama','Abiy Ahmed Ali','Donald Trump','Muhammadu Buhari'),1,'ইরিত্রিয়ার সঙ্গে দীর্ঘদিনের সীমান্ত বিরোধ মেটানো এবং শান্তি ও সমঝোতা প্রতিষ্ঠায় ভূমিকার জন্য ইথিওপিয়ার প্রধানমন্ত্রী আবি আহমেদ আলি ২০১৯ সালে শান্তিতে নোবেল পান।',false,'ok',73),array('geography','The largest waterfalls system in the world is',array('Angel Falls','Iguazu Falls','Victoria Falls','Niagara Falls'),1,'আর্জেন্টিনা-ব্রাজিল সীমান্তের ইগুয়াজু জলপ্রপাত শত শত প্রপাতের সমষ্টি, তাই একে বিশ্বের বৃহত্তম জলপ্রপাত ব্যবস্থা বলা হয়। সর্বোচ্চ জলপ্রপাত হলো অ্যাঞ্জেল।',false,'ok',74),array('intl-affairs','The European Union\'s working capital is in',array('London','Brussels','Lisbon','Austria'),1,'ইউরোপীয় ইউনিয়নের প্রধান প্রতিষ্ঠান ইউরোপীয় কমিশন ও কাউন্সিল বেলজিয়ামের ব্রাসেলসে অবস্থিত, তাই ব্রাসেলসকে EU-এর কার্যত রাজধানী বলা হয়।',false,'ok',75),array('science','The most abundant element in the Earth\'s crust is',array('Oxygen','Hydrogen','Carbon Dioxide','Silicon'),0,'ভূত্বকে সবচেয়ে বেশি পরিমাণে থাকা মৌল অক্সিজেন (ভরের প্রায় 46%), এর পরেই সিলিকন। কার্বন ডাই-অক্সাইড মৌল নয়, যৌগ।',false,'ok',76),array('bd-affairs','What is the timezone of Bangladesh?',array('UTC + 5','UTC + 4','UTC + 6','UTC + 3'),2,'বাংলাদেশের প্রমাণ সময় গ্রিনিচ মান সময়ের চেয়ে ৬ ঘণ্টা এগিয়ে, অর্থাৎ UTC + 6।',false,'ok',77),array('geography','The key factor in determining the weather is the quantity of .... in the atmosphere.',array('Water Vapor','Oxygen','Carbon Dioxide','Hydrogen'),0,'বায়ুমণ্ডলে জলীয় বাষ্পের পরিমাণ থেকেই আর্দ্রতা, মেঘ, বৃষ্টি ও ঝড় তৈরি হয়, তাই এটি আবহাওয়া নির্ধারণের মূল উপাদান।',false,'ok',78),array('science','Which from the following is NOT a renewable energy resource?',array('Geothermal','Nuclear','Biomass','Solar'),1,'পারমাণবিক শক্তি ইউরেনিয়ামের মতো সীমিত খনিজ জ্বালানির ওপর নির্ভরশীল, তাই এটি নবায়নযোগ্য নয়। ভূতাপীয়, জৈববস্তু ও সৌরশক্তি নবায়নযোগ্য।',false,'ok',79),array('intl-affairs','Which economic term is used to represent inequality in income distribution?',array('GDP','GNP','Gini','HDI'),2,'Gini সহগ (০ থেকে ১) দিয়ে আয় বণ্টনের অসমতা মাপা হয়; মান যত বেশি, অসমতা তত বেশি। GDP ও GNP উৎপাদনের পরিমাপ, আর HDI মানব উন্নয়নের সূচক।',false,'ok',80));
